// Neon Runner – simple infinite runner using the canvas with id="game"
// Controls: Arrow Up (jump), Arrow Down (slide)
// The player is a rectangle; obstacles are simple rectangles.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas with id "game" not found');
    return;
  }
  const ctx = canvas.getContext('2d');
  // Set canvas size to fill the window
  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // Game constants
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const SLIDE_TIME = 500; // ms
  const OBSTACLE_SPEED = 6;
  const OBSTACLE_INTERVAL = 1500; // ms

  // Player state
  const player = {
    width: 40,
    height: 80,
    x: 100,
    y: 0,
    vy: 0,
    onGround: false,
    sliding: false,
    slideTimer: 0,
    color: '#0ff',
  };

  // Obstacles array
  const obstacles = [];

  // Helper to create obstacle
  function spawnObstacle() {
    const type = Math.random() < 0.5 ? 'low' : 'high'; // low: requires jump, high: requires slide
    const width = 30 + Math.random() * 20;
    const height = type === 'low' ? 30 : 120;
    const y = type === 'low' ? canvas.height - height : canvas.height - player.height - 20; // high obstacle placed where player would hit if not sliding
    obstacles.push({ x: canvas.width + width, y, width, height, type, passed: false });
  }

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'ArrowUp' && player.onGround && !player.sliding) {
      player.vy = JUMP_VELOCITY;
      player.onGround = false;
    }
    if (e.code === 'ArrowDown' && !player.sliding && player.onGround) {
      player.sliding = true;
      player.slideTimer = SLIDE_TIME;
      // Reduce height while sliding
      player.height = 40;
    }
  });
  window.addEventListener('keyup', e => {
    keys[e.code] = false;
  });

  let lastTime = 0;
  let obstacleTimer = 0;
  let score = 0;
  let gameOver = false;

  function update(dt) {
    if (gameOver) return;
    // Player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    // ground check
    const groundY = canvas.height - player.height;
    if (player.y >= groundY) {
      player.y = groundY;
      player.vy = 0;
      player.onGround = true;
    }
    // Slide timer
    if (player.sliding) {
      player.slideTimer -= dt;
      if (player.slideTimer <= 0) {
        player.sliding = false;
        player.height = 80; // restore height
      }
    }
    // Obstacles
    obstacleTimer += dt;
    if (obstacleTimer >= OBSTACLE_INTERVAL) {
      obstacleTimer = 0;
      spawnObstacle();
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= OBSTACLE_SPEED;
      // Collision detection (simple AABB)
      if (!o.passed &&
          player.x < o.x + o.width &&
          player.x + player.width > o.x &&
          player.y < o.y + o.height &&
          player.y + player.height > o.y) {
        // Collision – game over
        gameOver = true;
      }
      // Score when passing obstacle
      if (!o.passed && o.x + o.width < player.x) {
        o.passed = true;
        score++;
      }
      // Remove off‑screen
      if (o.x + o.width < 0) {
        obstacles.splice(i, 1);
      }
    }
  }

  function render() {
    // Clear background (dark neon)
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);
    // Draw obstacles
    ctx.fillStyle = '#f0f';
    obstacles.forEach(o => {
      ctx.fillRect(o.x, o.y, o.width, o.height);
    });
    // Draw score
    ctx.fillStyle = '#fff';
    ctx.font = '20px monospace';
    ctx.fillText('Score: ' + score, 20, 30);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f55';
      ctx.font = '48px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    render();
    if (!gameOver) requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
